"""nl — virtues_c."""

T = {
"virtues_051": ("Wat raadt Luqman zijn zoon aan over de stem?", ["Die te verlagen: de meest weerzinwekkende stem is het gebalk van de ezel", "Zeer luid te spreken", "Nooit te spreken", "Al lopend te zingen"], "«En wees gematigd in je pas en verlaag je stem: voorwaar, de meest weerzinwekkende van de geluiden is de stem van ezels.»"),
"virtues_052": ("Welke drie raadgevingen geeft Luqman zijn zoon voordat hij over geduld spreekt?", ["Onderhoud het gebed, gebied het goede, verbied het verwerpelijke", "Reizen, handelen, schrijven", "Weinig eten, weinig slapen, weinig spreken", "Bouwen, planten, oogsten"], "«Mijn zoon, onderhoud het gebed, gebied het goede, verbied het verwerpelijke, en wees geduldig onder wat jou treft.»"),
"virtues_053": ("Welke drie eigenschappen geeft de Koran de godvrezenden, in soera Al-'Imran?", ["Besteden in voorspoed en tegenspoed, de woede bedwingen, de mensen vergeven", "Vasten, nachtgebed, zwijgen", "Bouwen, planten, geven", "Reizen, leren, onderwijzen"], "«Zij die besteden in voorspoed en in tegenspoed, en die de woede bedwingen en de mensen vergeven — en Allah houdt van hen die goed doen.»"),
"virtues_054": ("Wat acht de Koran beter dan een aalmoes gevolgd door krenking?", ["Een vriendelijk woord en vergeving", "Een grotere gift", "Volledig zwijgen", "Een eed"], "«Een vriendelijk woord en vergeving zijn beter dan een aalmoes gevolgd door krenking.»"),
"virtues_055": ("Wat zegt de Koran over in het geheim gegeven aalmoezen?", ["Zij zijn beter voor de gever", "Zij tellen niet", "Zij moeten aangekondigd worden", "Zij zijn verboden"], "«Als jullie jullie aalmoezen openlijk geven, dan is dat goed; maar als jullie ze verbergen en aan de armen geven, dan is dat beter voor jullie.»"),
"virtues_056": ("Wat verbiedt de Koran als aalmoes te geven?", ["Wat men zelf slechts met gesloten ogen zou aannemen", "Wat nieuw is", "Wat men liefheeft", "Wat uit een erfenis komt"], "«En kies daaruit niet het slechte om te besteden, wat jullie zelf slechts met gesloten ogen zouden aannemen.»"),
"virtues_057": ("Wanneer wordt de ware vroomheid bereikt, volgens soera Al-'Imran?", ["Door te besteden van wat men liefheeft", "Door het overschot te besteden", "Door in het openbaar te besteden", "Door alles te houden"], "«Jullie zullen de vroomheid nooit bereiken totdat jullie besteden van wat jullie liefhebben.»"),
"virtues_058": ("Welk beeld gebruikt de Koran voor evenwicht in het besteden?", ["De hand niet aan de nek geketend houden, noch haar geheel uitstrekken", "De deur sluiten", "Langzaam lopen", "Tweemaal tellen"], "«En houd je hand niet aan je nek geketend, noch strek haar geheel uit, anders zit je berispt en berooid neer.»"),
"virtues_059": ("Hoe beschrijft de Koran het besteden van «de dienaren van de Erbarmer»?", ["Noch verkwistend noch gierig, maar daartussenin", "Altijd mateloos geven", "Altijd sparen", "Nooit geven"], "«En zij die, wanneer zij besteden, niet verkwistend en niet gierig zijn, maar het midden daartussen houden.»"),
"virtues_060": ("Wat gebiedt de Koran voordat men een huis binnengaat dat niet het zijne is?", ["Toestemming te vragen en de bewoners te groeten", "Driemaal te kloppen en dan binnen te gaan", "Rechtstreeks binnen te gaan", "Van ver te roepen"], "«Treed geen huizen binnen die niet de jullie zijn totdat jullie toestemming hebben gevraagd en de bewoners hebben gegroet.»"),
"virtues_061": ("Wat moet men doen als men gevraagd wordt terug te keren, volgens soera An-Nur?", ["Terugkeren: dat is reiner voor jullie", "Aandringen", "Bij de deur wachten", "Toch binnengaan"], "«En als jullie gezegd wordt: “Keer terug”, keer dan terug; dat is reiner voor jullie.»"),
"virtues_062": ("Wat gebiedt de Koran wanneer een onbetrouwbaar persoon nieuws brengt?", ["Het na te gaan, opdat men niemand uit onwetendheid schaadt", "Het meteen te verspreiden", "Het op te schrijven", "Het altijd te negeren"], "«Als een verdorvene tot jullie met een bericht komt, onderzoek het dan, opdat jullie geen mensen uit onwetendheid schaden en er dan spijt van krijgen.»"),
"virtues_063": ("Welk gedrag verbiedt soera Al-Hujurat, naast achterklap?", ["Spioneren en overmatig wantrouwen", "Alleen reizen", "Zacht spreken", "Brieven schrijven"], "«O jullie die geloven, vermijd veel vermoedens; voorwaar, sommige vermoedens zijn zonde. En bespioneer elkaar niet en spreek geen kwaad over elkaar.»"),
"virtues_064": ("Wat gebiedt de Koran wanneer twee groepen gelovigen strijden?", ["Hen met rechtvaardigheid te verzoenen", "Partij te kiezen", "Hen te negeren", "Hen alleen met geweld te scheiden"], "«En als twee groepen van de gelovigen strijden, verzoen hen dan… en handel rechtvaardig. Voorwaar, Allah houdt van hen die rechtvaardig handelen.»"),
"virtues_065": ("Wat verbiedt de Koran uitdrukkelijk, zelfs tegenover een volk dat men verafschuwt?", ["Haat de rechtvaardigheid laten verdringen", "De handel", "Het spreken", "Het nabuurschap"], "«En laat de haat jegens een volk jullie er niet toe brengen onrechtvaardig te zijn. Wees rechtvaardig; dat is dichter bij de godvrezendheid.»"),
"virtues_066": ("Tegen wie eist de Koran een rechtvaardige getuigenis, indien nodig?", ["Tegen zichzelf, zijn ouders en zijn verwanten", "Alleen tegen vreemden", "Alleen tegen de rijken", "Alleen tegen de armen"], "«Wees standvastig in rechtvaardigheid, getuigen voor Allah, ook al is het tegen jullie zelf of tegen de ouders en de verwanten.»"),
"virtues_067": ("Wat gebiedt de Koran terug te geven aan wie er recht op heeft?", ["De toevertrouwde goederen (amanat)", "Brieven", "Oogsten", "Verhalen"], "«Voorwaar, Allah gebiedt jullie het toevertrouwde terug te geven aan wie er recht op heeft, en wanneer jullie tussen de mensen oordelen, met rechtvaardigheid te oordelen.»"),
"virtues_068": ("Welke personen somt vers 4:36 op voor goede behandeling, na de ouders?", ["Verwanten, wezen, armen, de nabije en verre buur, de metgezel, de reiziger en de dienaar", "Koningen en leiders", "Kooplieden", "Alleen geleerden"], "«Aanbid Allah en ken Hem geen deelgenoten toe, en doe goed aan de ouders, aan de verwanten, de wezen, de behoeftigen, de nabije buur, de verre buur, de metgezel aan je zijde, de reiziger, en hen die jullie rechterhanden bezitten.»"),
"virtues_069": ("Wat gebiedt de Koran ten aanzien van een schuldenaar in moeilijkheden?", ["Hem uitstel te geven tot hij ruimte heeft", "Hem te vervolgen", "De schuld te verdubbelen", "Hem te verdrijven"], "«En als iemand in moeilijkheden verkeert, laat er dan uitstel zijn tot een tijd van ruimte. Maar als jullie het als aalmoes schenken, is dat beter voor jullie.»"),
"virtues_070": ("Wat gebiedt het langste vers van de Koran voor een schuld met een vastgestelde termijn?", ["Dat zij opgeschreven wordt", "Dat zij geheim blijft", "Dat zij vergeten wordt", "Dat zij mondeling wordt doorgegeven"], "«O jullie die geloven, wanneer jullie een schuld aangaan voor een vastgestelde termijn, schrijf haar dan op.»"),
"virtues_071": ("Wat verbiedt de Koran aangaande het bezit van anderen?", ["Het onrechtmatig verteren, of het gebruiken om rechters om te kopen", "Het tellen", "Het verkopen", "Het bewaren"], "«En verteer elkaars bezit niet op onrechtmatige wijze, en breng het niet naar de rechters om zondig een deel van het bezit van de mensen te verteren.»"),
"virtues_072": ("Wat gebiedt de Koran aangaande het bezit van wezen?", ["Het hun te geven, zonder het goede voor het slechte te verruilen", "Het te verdelen", "Het te verkopen", "Het levenslang te houden"], "«En geef de wezen hun bezittingen en verruil het slechte niet voor het goede, en verteer hun bezittingen niet samen met de jullie.»"),
"virtues_073": ("Hoe gebiedt de Koran te meten en te wegen?", ["Geef volle maat en weeg met een zuivere weegschaal", "Afronden in eigen voordeel", "Op het oog wegen", "Tweemaal meten"], "«En geef volle maat wanneer jullie meten, en weeg met een zuivere weegschaal. Dat is het beste en de mooiste uitkomst.»"),
"virtues_074": ("Wat verbiedt de Koran te volgen, bij gebrek aan kennis?", ["Dat waarover men geen kennis heeft: het gehoor, het gezicht en het hart zullen ondervraagd worden", "De kortste weg", "De karavanen", "Het zwijgen"], "«En volg niet dat waarover jij geen kennis hebt. Voorwaar, het gehoor, het gezicht en het hart — over dat alles zal ondervraagd worden.»"),
"virtues_075": ("Welk beeld geeft de Koran van hoogmoed in de tred?", ["Je kunt de aarde niet splijten, noch de bergen in hoogte bereiken", "Je gaat sneller", "Je vermoeit minder", "Je verdient respect"], "«En loop niet verwaand op de aarde. Voorwaar, jij zult de aarde nooit splijten, en jij zult de bergen nooit in hoogte bereiken.»"),
"virtues_076": ("Welke hoedanigheid van het spreken gebiedt de Koran, met de belofte dat de daden goedgemaakt worden?", ["Oprecht, waarachtig spreken (qawl sadid)", "Kort spreken", "Geleerd spreken", "Schriftelijk spreken"], "«O jullie die geloven, vrees Allah en spreek juiste woorden. Hij zal jullie daden goedmaken en jullie zonden vergeven.»"),
"virtues_077": ("Welk soort spreken werd zelfs tegenover een tiran geboden, in de Koran?", ["Zachte woorden", "Dreigende woorden", "Spottende woorden", "Zwijgen"], "«En spreek tot hem met zachte woorden, opdat hij zich laat vermanen of Allah vreest.»"),
"virtues_078": ("Over wie zegt de Koran dat zijn woord het beste is?", ["Wie tot Allah oproept, rechtschapen handelt en zegt: ik behoor tot de moslims", "De dichter", "De redenaar", "De rechter"], "«En wie is beter in spreken dan wie tot Allah oproept en rechtschapen handelt en zegt: voorwaar, ik behoor tot de moslims?»"),
"virtues_079": ("Waarvan wenden de welslagende gelovigen zich af, volgens Al-Mu'minun?", ["Van nutteloos gepraat (al-laghw)", "Van het werk", "Van het reizen", "Van de maaltijden"], "«En zij die zich afwenden van nutteloos gepraat.»"),
"virtues_080": ("Welke twee verplichtingen bewaken de welslagende gelovigen, volgens Al-Mu'minun?", ["Hun toevertrouwde goederen en hun beloften", "Vasten en nachtgebed", "Reizen en handel", "Schrijven en lezen"], "«En zij die zorgvuldig zijn met wat hun is toevertrouwd en met hun beloften.»"),
"virtues_081": ("Wat zegt de Koran over wie vergeeft en verzoent, hoewel hij kwaad met kwaad zou kunnen vergelden?", ["Zijn beloning rust bij Allah", "Hij verliest zijn recht", "Hij wordt berispt", "Hij moet zwijgen"], "«En de vergelding voor een slechte daad is een slechte daad gelijk daaraan, maar wie vergeeft en verzoent — zijn beloning rust bij Allah.»"),
"virtues_082": ("Welk argument geeft de Koran om iemand te vergeven die jou onrecht heeft aangedaan?", ["«Houden jullie er niet van dat Allah jullie vergeeft?»", "«Je wordt in geld betaald»", "«Het maakt je machtig»", "«Het bespaart je een rechtszaak»"], "«Laat hen vergeven en door de vingers zien. Houden jullie er niet van dat Allah jullie vergeeft? En Allah is Vergevensgezind, Barmhartig.»"),
"virtues_083": ("Welke drie aanwijzingen brengt vers 7:199 samen?", ["Neem wat vrijelijk gegeven wordt, gebied het goede, wend je af van de onwetenden", "Strijden, vluchten, zwijgen", "Eten, drinken, slapen", "Tellen, schrijven, lezen"], "«Neem wat vrijelijk gegeven wordt, gebied het goede, en wend je af van de onwetenden.»"),
"virtues_084": ("Welke houding beveelt de Koran aan bij kwetsende woorden en beproeving?", ["Geduld en godvrezendheid: dat behoort tot de zaken die vastberadenheid vergen", "Onmiddellijk antwoord", "Blijvende terugtrekking", "Minachtend zwijgen"], "«En jullie zullen zeker veel beledigingen horen van hen die vóór jullie de Schrift kregen. Maar als jullie geduldig zijn en Allah vrezen, dan behoort dat tot de zaken die vastberadenheid vergen.»"),
"virtues_085": ("Hoe beschrijft de Koran geduld en vergeving?", ["Zij behoren tot de zaken die vastberadenheid vergen", "Zij zijn zwakte", "Zij zijn vrijblijvend", "Zij zijn alleen voor geleerden"], "«En wie geduldig is en vergeeft — voorwaar, dat behoort tot de zaken die vastberadenheid vergen.»"),
"virtues_086": ("Voor wie is het gebed volgens de Koran niet zwaar?", ["Voor de deemoedigen (al-khashi'in)", "Voor de rijken", "Voor de geleerden", "Voor de reizigers"], "«En zoek hulp door geduld en gebed; voorwaar, het is zwaar behalve voor de deemoedigen.»"),
"virtues_087": ("Waaraan herinnert de Koran over wat men verafschuwt of liefheeft?", ["Je kunt iets verafschuwen dat goed voor je is, en iets liefhebben dat slecht voor je is", "Wat je liefhebt is altijd goed", "Wat je verafschuwt is altijd slecht", "Je weet altijd wat goed is"], "«Misschien haten jullie iets terwijl het goed voor jullie is; en misschien houden jullie van iets terwijl het slecht voor jullie is. Allah weet, en jullie weten niet.»"),
"virtues_088": ("Wat belooft de Koran aan wie Allah vreest, wat betreft uitkomst en voorziening?", ["Een uitweg, en voorziening vanwaar hij het niet verwacht", "Onmiddellijke rijkdom", "Een lange reis", "Een openbaar ambt"], "«En wie Allah vreest, voor hem maakt Hij een uitweg, en Hij voorziet hem vanwaar hij het niet verwacht.»"),
"virtues_089": ("Welke dankbaarheid gebiedt de Koran in één adem met dankbaarheid jegens Allah?", ["Dankbaarheid jegens de ouders", "Jegens zijn meester", "Jegens zijn buur", "Jegens zijn koning"], "«Wees Mij dankbaar en jegens je ouders; tot Mij is de uiteindelijke terugkeer.»"),
"virtues_090": ("Welke grens stelt de Koran aan de gehoorzaamheid aan de ouders?", ["Hen niet te gehoorzamen als zij gebieden anderen aan Allah toe te kennen", "Hen nooit te gehoorzamen", "Hen in alles te gehoorzamen", "Hen alleen onderweg te gehoorzamen"], "«Maar als zij zich inspannen om jou aan Mij deelgenoten toe te kennen waarover jij geen kennis hebt, gehoorzaam hen dan niet; maar ga in deze wereld met hen om op passende wijze.»"),
"virtues_091": ("Welke smeekbede leert de Koran voor de eigen ouders en het nageslacht?", ["Dankbaar te zijn voor de gunst, goed te doen, en dat het nageslacht rechtschapen wordt", "Om rijkdom te vragen", "Om een lange reis te vragen", "Om een ambt te vragen"], "«Mijn Heer, stel mij in staat dankbaar te zijn voor Uw gunst die U aan mij en aan mijn ouders hebt geschonken, en rechtschapen te handelen; en maak mijn nageslacht rechtschapen voor mij.»"),
"virtues_092": ("Wat vragen «de dienaren van de Erbarmer» aangaande hun families?", ["Dat zij een verkoeling van de ogen zijn, en dat zij een voorbeeld voor de godvrezenden zijn", "Dat zij rijk zijn", "Dat zij talrijk zijn", "Dat zij reizen"], "«Onze Heer, schenk ons in onze echtgenoten en ons nageslacht een verkoeling van de ogen, en maak ons tot een voorbeeld voor de godvrezenden.»"),
"virtues_093": ("Hoe gedragen «de dienaren van de Erbarmer» zich tegenover lichtzinnigheid?", ["Zij gaan er waardig aan voorbij", "Zij blijven staan luisteren", "Zij antwoorden scherp", "Zij schrijven het op"], "«En zij die geen valse getuigenis afleggen, en wanneer zij langs nutteloos gepraat komen, gaan zij er waardig aan voorbij.»"),
"virtues_094": ("Wat gebiedt de Koran in een bijeenkomst wanneer om plaats wordt gevraagd?", ["Maak plaats: Allah zal ruimte voor jullie maken", "Blijf opeengepakt", "Vertrek", "Zwijg"], "«O jullie die geloven, wanneer jullie gezegd wordt: “Maak plaats in de bijeenkomsten”, maak dan plaats; Allah zal ruimte voor jullie maken.»"),
"virtues_095": ("Bij wie gebiedt de Koran te zijn, in soera At-Tawbah?", ["Bij de waarachtigen", "Bij de machtigen", "Bij de rijken", "Bij de reizigers"], "«O jullie die geloven, vrees Allah en wees met de waarachtigen.»"),
"virtues_096": ("Met wie gebiedt de Koran de Profeet ﷺ geduldig gezelschap te houden, in Al-Kahf?", ["Zij die hun Heer 's ochtends en 's avonds aanroepen, Zijn aangezicht zoekend", "De stamhoofden", "De rijke kooplieden", "De dichters"], "«En houd jezelf geduldig bij hen die hun Heer 's ochtends en 's avonds aanroepen, Zijn aangezicht zoekend; en laat jouw ogen niet aan hen voorbijgaan.»"),
"virtues_097": ("Waarin gebiedt de Koran elkaar te helpen, en waarin verbiedt zij dat?", ["Help elkaar in vroomheid en godvrezendheid, niet in zonde en vijandschap", "Help elkaar in alles", "Help niemand", "Help elkaar alleen binnen de familie"], "«En help elkaar in vroomheid en godvrezendheid, maar help elkaar niet in zonde en vijandschap.»"),
"virtues_098": ("Wat gebiedt de Koran over een gesloten verbond en bekrachtigde eden?", ["Het verbond na te komen en eden na bekrachtiging niet te breken", "Ze opnieuw te onderhandelen", "Ze te vergeten", "Ze te verbergen"], "«En kom het verbond met Allah na wanneer jullie het zijn aangegaan, en breek de eden niet na hun bekrachtiging.»"),
"virtues_099": ("Wanneer is volgens een door al-Bukhari overgeleverde hadith het geloof van een man volledig?", ["Wanneer hij voor zijn broeder liefheeft wat hij voor zichzelf liefheeft", "Wanneer hij het hele jaar vast", "Wanneer hij al zijn bezit weggeeft", "Wanneer hij naar Mekka reist"], "«Niemand van jullie gelooft werkelijk totdat hij voor zijn broeder liefheeft wat hij voor zichzelf liefheeft.»"),
"virtues_100": ("In welke gevallen ziet de Koran goeds in een vertrouwelijk gesprek?", ["Aansporen tot een aalmoes, tot het goede, of tot verzoening tussen mensen", "Zaken bespreken", "Een reis plannen", "Nieuws doorgeven"], "«Er is geen goeds in veel van hun vertrouwelijke gesprekken, behalve bij wie aanspoort tot een aalmoes of tot het goede of tot verzoening tussen de mensen.»"),
}
